{
  "tables": [
    {
      "table_name": "components",
      "columns": [
        {
          "name": "component_id",
          "type": "INTEGER",
          "description": "Unique identifier for each component"
        },
        {
          "name": "component_name",
          "type": "VARCHAR",
          "description": "Name of the component"
        },
        {
          "name": "component_type",
          "type": "VARCHAR",
          "description": "Type of the component (e.g., IC, transistor)"
        },
        {
          "name": "manufacturer",
          "type": "VARCHAR",
          "description": "Manufacturer of the component"
        },
        {
          "name": "date_added",
          "type": "DATE",
          "description": "Date when the component was added to the system"
        },
        {
          "name": "component_category",
          "type": "VARCHAR",
          "description": "Category of the component (e.g., Analog, Digital)"
        },
        {
          "name": "datasheet_url",
          "type": "VARCHAR",
          "description": "URL of the component's datasheet"
        },
        {
          "name": "lifecycle_status",
          "type": "VARCHAR",
          "description": "Lifecycle status (Active, Obsolete, Development)"
        }
      ],
      "primary_key": [
        "component_id"
      ]
    },
    {
      "table_name": "specifications",
