        {
          "name": "spec_id",
          "type": "INTEGER",
          "description": "Unique identifier for each specification"
        },
        {
          "name": "component_id",
          "type": "INTEGER",
          "description": "Reference to the component the specification belongs to"
        },
        {
          "name": "parameter_id",
          "type": "INTEGER",
          "description": "Reference to the parameter being specified"
        },
        {
          "name": "condition_id",
          "type": "INTEGER",
          "description": "Reference to any condition applicable to the specification"
        },
        {
          "name": "range",
          "type": "VARCHAR",
          "description": "Range of values the parameter can take"
        },
        {
          "name": "unit",
          "type": "VARCHAR",
          "description": "Unit of measurement for the parameter"
        },
        {
          "name": "spec_revision",
          "type": "VARCHAR",
          "description": "Specification revision number"
        },
        {
          "name": "spec_date",
          "type": "DATE",
          "description": "Date of the specification"
        },
        {
          "name": "max_tolerance",
          "type": "FLOAT",
          "description": "Maximum tolerance allowed for the parameter"
        }
      ],
      "primary_key": [
        "spec_id"
      ]
    },
    {
      "table_name": "compliance",
      "columns": [
        {
          "name": "compliance_id",
          "type": "INTEGER",
          "description": "Unique identifier for each compliance record"
        },
        {
          "name": "component_id",
          "type": "INTEGER",
          "description": "Reference to the component"
        },
        {
          "name": "standard",
          "type": "VARCHAR",
          "description": "Industry standard the component is evaluated against"
        },
        {
          "name": "compliance_status",
          "type": "VARCHAR",
          "description": "Compliance status (e.g., compliant, non-compliant)"
        },
        {
          "name": "last_checked",
          "type": "DATE",
          "description": "Date when compliance was last checked"
        },
        {
          "name": "compliance_notes",
          "type": "TEXT",
          "description": "Additional notes on compliance evaluation"
        },
        {
          "name": "reviewed_by",
          "type": "INTEGER",
          "description": "User ID of the compliance reviewer"
        }
      ],
      "primary_key": [
        "compliance_id"
      ]
    },
    {
      "table_name": "users",
      "columns": [
        {
          "name": "user_id",
          "type": "INTEGER",
          "description": "Unique identifier for each user"
        },
        {
          "name": "user_name",
          "type": "VARCHAR",
          "description": "Full name of the user"
        },
        {
          "name": "email",
          "type": "VARCHAR",
          "description": "Email address of the user"
        },
        {
          "name": "role",
          "type": "VARCHAR",
          "description": "Role of the user (e.g., engineer, compliance officer, admin)"
        },
        {
          "name": "department",
          "type": "VARCHAR",
          "description": "Department to which the user belongs"
        },
        {
          "name": "last_login",
          "type": "TIMESTAMP",
          "description": "Last login time of the user"
        }
      ],
      "primary_key": [
        "user_id"
      ]
    },
    {
      "table_name": "component_history",
      "columns": [
        {
