        },
        {
          "name": "change_description",
          "type": "TEXT",
          "description": "Description of the change made"
        },
        {
          "name": "changed_by",
          "type": "INTEGER",
          "description": "User ID of the person who made the change"
        },
        {
          "name": "change_date",
          "type": "DATE",
          "description": "Date when the change was made"
        }
      ],
      "primary_key": [
        "history_id"
      ]
    },
    {
