          "type": "VARCHAR",
          "description": "Name of the standard"
        },
        {
          "name": "description",
          "type": "TEXT",
          "description": "Description of the standard"
        },
        {
          "name": "applicable_regulations",
          "type": "TEXT",
          "description": "Regulations applicable under this standard"
        }
      ],
      "primary_key": [
        "standard_id"
      ]
    },
    {
