      "columns": [
        {
          "name": "analysis_id",
          "type": "INTEGER",
          "description": "Unique identifier for each failure analysis record"
        },
        {
          "name": "component_id",
          "type": "INTEGER",
          "description": "Reference to the component"
        },
        {
          "name": "potential_issues",
          "type": "TEXT",
          "description": "Potential issues identified"
        },
        {
          "name": "failure_probability",
          "type": "FLOAT",
          "description": "Probability of failure"
        },
        {
          "name": "analysis_date",
          "type": "DATE",
          "description": "Date of the failure analysis"
        }
      ],
      "primary_key": [
        "analysis_id"
      ]
